CREATE OR REPLACE PROCEDURE dbp_macro.m_ups_ts_wbs_initiale_belieferung_standard(IN P_MANDANT_ID INT64, IN P_AUSLIEFERGRUPPE_ID STRING, IN P_WERBE_START_WTAG_ID INT64, IN P_WERBE_ENDE_WTAG_ID INT64, IN P_ANZ_TAGE_WERBE_DAUER INT64, IN P_INIT_LIEF_MARKT_CLUSTER_ID INT64, IN P_ESTIMATION_ID INT64, IN P_ANZ_AME_SPLIT_GRENZE INT64, IN P_AUTO_SPLIT_FG INT64, IN P_AUTO_SPLIT_PROZENT INT64, IN P_ANZ_PAL_AUTO_SPLIT_GRENZE INT64, IN P_ANZ_TAGE_VOR_AKT_LIEFERSTART_AUTO_SPLIT_AME INT64, IN P_ANZ_TAGE_VOR_AKT_LIEFERSTART_AUTO_SPLIT_PAL INT64, IN P_ANZ_TAGE_AUTO_SPLIT_PAL INT64, IN P_ANZ_TAGE_FIX_SPLIT_MHD_GRENZE INT64, IN P_ANZ_TAGE_PHASE_SWITCH_I INT64, IN P_ANZ_TAGE_PHASE_SWITCH_II INT64, IN P_ANZ_TAGE_PHASE_SWITCH_III INT64, IN P_ANZ_TAGE_PHASE_SWITCH_IV INT64, IN P_UNTER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UNTER_MHD_GRENZE_9_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT INT64, IN P_UEBER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_P