R_MHD_GRENZE_1_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_2_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_3_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_4_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_5_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_6_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_7_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_8_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent, P_UNTER_MHD_GRENZE_9_TAGE_NACH_WERBESTART_FIX_SPLIT_PROZENT AS unter_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_7_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_7_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_6_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_6_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_5_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_5_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_4_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_4_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_3_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_2_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_1_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent, P_UEBER_MHD_GRENZE_0_TAGE_VOR_WERBESTART_FIX_SPLIT_PROZENT AS ueber_