WHEN MATCHED AND P_DELETE_FG = 0 THEN UPDATE SET
    anz_ame_split_grenze = IFNULL(source.anz_ame_split_grenze, 0) ,
    auto_split_fg = source.auto_split_fg ,
    auto_split_prozent = IFNULL(source.auto_split_prozent, 0) ,
    anz_pal_auto_split_grenze = IFNULL(source.anz_pal_auto_split_grenze, 0) ,
    anz_tage_vor_akt_lieferstart_auto_split_ame = IFNULL(source.anz_tage_vor_akt_lieferstart_auto_split_ame, 0) ,
    anz_tage_vor_akt_lieferstart_auto_split_pal = IFNULL(source.anz_tage_vor_akt_lieferstart_auto_split_pal, 0) ,
    anz_tage_auto_split_pal = IFNULL(source.anz_tage_auto_split_pal, 0) ,
    anz_tage_fix_split_mhd_grenze = IFNULL(source.anz_tage_fix_split_mhd_grenze, 0) ,
    anz_tage_phase_switch_i = IFNULL(source.anz_tage_phase_switch_i, 0) ,
    anz_tage_phase_switch_ii = IFNULL(source.anz_tage_phase_switch_ii, 0) ,
    anz_tage_phase_switch_iii = IFNULL(source.anz_tage_phase_switch_iii, 0) ,
    anz_tage_phase_switch_iv = IFNULL(source.anz_tage_phase_switch_iv, 0) ,
    td_update = CURRENT_TIMESTAMP()
WHEN MATCHED AND P_DELETE_FG = 1 THEN
DELETE
