e.ueber_mhd_grenze_3_tage_vor_werbestart_fix_split_prozent , source.ueber_mhd_grenze_2_tage_vor_werbestart_fix_split_prozent , source.ueber_mhd_grenze_1_tage_vor_werbestart_fix_split_prozent , source.ueber_mhd_grenze_0_tage_vor_werbestart_fix_split_prozent , source.ueber_mhd_grenze_1_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_2_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_3_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_4_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_5_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_6_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_7_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_8_tage_nach_werbestart_fix_split_prozent , source.ueber_mhd_grenze_9_tage_nach_werbestart_fix_split_prozent , IFNULL(source.anz_tage_phase_switch_i, 0) , IFNULL(source.anz_tage_phase_switch_ii, 0) , IFNULL(source.anz_tage_phase_switch_iii, 0) , IFNULL(source.anz_tage_phase_switch_iv, 0) , CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
COMMIT TRANSACTION;
SET out_param  =  'Freeze Writeback angepasst';
SELECT out_param;
RETURN;
END;


